mapper.select:
/** com.secta.hcbatch.job.message.mapper.HcMsgMapper.selectMsgSeq */
SELECT TO_CHAR(EM_TRAN_MMS_SEQ.NEXTVAL) AS MMS_SEQ
FROM DUAL

/** com.secta.hcbatch.job.message.mapper.HcMsgMapper.selectOrderInfo */
SELECT A.CART_NO
     , A.USER_ID
FROM T_ORDER A
WHERE A.ORDER_NO = #{orderNo}

mapper.update:
/** com.secta.hcbatch.job.message.mapper.HcMsgMapper.updateMsgErrorInfo */
UPDATE T_HAPPYCON_MMS A
SET A.MMS_AT_FILE = #{errMsg}
WHERE A.TRIG_DATE = TO_TIMESTAMP(#{taskDtm}, 'YYYYMMDDHH24MISSFF9')
  AND A.TRIG_SEQ = TO_NUMBER(#{taskNo})

mapper.insert:
/** com.secta.hcbatch.job.message.mapper.HcMsgMapper.insertSendImage */
INSERT INTO EM_TRAN_MMS
( MMS_SEQ
, FILE_CNT
, MMS_BODY
, MMS_SUBJECT
, FILE_TYPE1
, FILE_NAME1
, SERVICE_DEP1)
VALUES ( TO_NUMBER(#{mmsSeq})
       , TO_NUMBER(#{imgCnt})
       , #{mmsCtt}
       , #{mmsSubj}
       , #{mmsType}
       , #{mmsImg}
       , 'ALL')
